//! The `Diagram` trait (feature `diagram`).

use crate::diagram;

/// State diagram of a machine generated by [`sml!`](crate::sml) (feature `diagram`).
///
/// With the feature on, `sml!` also embeds the diagram in the machine's rustdoc.
/// That embedded copy shows composite states by reference; this runtime graph nests
/// each sub-machine's diagram inside its composite state.
pub trait Diagram {
    /// The machine's states and transitions; composite states contain their sub-machine.
    fn graph() -> diagram::Graph;

    /// Standalone SVG (own light/dark palette), e.g. to write to a `.svg` file.
    #[must_use]
    fn diagram_svg() -> String {
        #[expect(
            clippy::expect_used,
            reason = "generated graphs only reference their own nodes, so rendering cannot fail"
        )]
        diagram::render_svg(&Self::graph(), diagram::Style::Standalone)
            .expect("sml! generated an invalid diagram graph")
    }
}
